-- Midnight in Salem: Deirdre in the convertible, 3D version - convo globals.
-- Generated by make_mid_car3d_scenes.py; edit the generator. Plate version: DS_CAR_Global_SC.
AreaTag("DSCarConvo")
AreaTag("PREVENTALLUIBUTMENU")
Brain.InConvo_BR = true
Scene:Include("ConvoSystem_SC")
Scene:Include("Table_SC")
-- Back to front: road loop, car plate, steering wheel loop, Deirdre (3D) in front of the wheel
-- (looping movies on the same shared clocks as the plate version).
roadMOV = AR:Movie({movie = "CAR_ConvertibleRoad_ANIM", onScreen = Rect:New(0, 0, 1024, 690), loop = true, clock = "CAR_Road", z = -1})
carOVL = AR:Overlay({ovl = "CAR_Convertible_OVL", z = 1})
deirdre = AR:Model({
  model = "DS_Deirdre_MDL",
  rotatable = false,
  camera = {eye = {x = -0.1800, y = 1.0490, z = 0.4685}, target = {x = -0.0904, y = 0.9561, z = -0.5231},
    up = {x = 0.0240, y = 0.9956, z = -0.0911}, fov = 42, near = 0.05, far = 20},
  z = 5
})
wheelMOV = AR:Movie({movie = "CAR_ConvertibleWheel_CNV", onScreen = Rect:New(0, 0, 276, 376), loop = true, clock = "CAR_Wheel", z = 3})
deirdre:Play(1, "Deirdre_Driving", {loop = true})
AR:Timer({
  minDuration = 2.5,
  maxDuration = 6,
  OnDone = function(this)
    deirdre:Play(3, "Deirdre_Blink", {loop = false, fade = 0.05})
    this:Restart()
  end
})
-- Face clips follow the convo: clips[i] is stage i's clip (false = a Nancy line, Deirdre
-- listens). Stage 1 starts with the scene; each "convoAudioDone" moves to the next.
function DSCar3DLines(clips)
  local i = 1
  local function start()
    local clip = clips[i]
    if clip then
      deirdre:Play(2, clip, {loop = false, fade = 0.15})
    else
      deirdre:Stop(2, 0.3)
    end
  end
  start()
  MakeActor({
    name = "",
    initialState = "run",
    states = {
      run = {
        OnEvent("global", "convoAudioDone", function(this)
          i = i + 1
          start()
        end)
      }
    }
  })
end
